/**
 * Generated by scaffold-listing-primitives. `data-component="row-actions"`.
 *
 * The per-row ⋯ menu (view / edit / delete). Pass only the actions the role is
 * actually allowed to take — an action with no handler is not rendered, so a
 * read-only role gets a shorter menu rather than a row of dead buttons.
 * If no action survives, the whole control renders nothing.
 *
 * Usage:
 *   <RowActions
 *     testId={`user-${row.id}`}
 *     onView={() => navigate(row.id)}
 *     onEdit={canEdit ? () => openEdit(row) : undefined}
 *     onDelete={canDelete ? () => confirmDelete(row) : undefined}
 *   />
 */
import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

export interface RowActionsProps {
  testId: string;
  onView?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  /** Anything beyond the standard three (e.g. "Resend invite"). */
  extra?: { label: string; onSelect: () => void; destructive?: boolean }[];
}

export function RowActions({ testId, onView, onEdit, onDelete, extra }: RowActionsProps) {
  const { t } = useTranslation('common');
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onDocClick(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    }
    function onEsc(e: KeyboardEvent) {
      if (e.key === 'Escape') setOpen(false);
    }
    document.addEventListener('mousedown', onDocClick);
    document.addEventListener('keydown', onEsc);
    return () => {
      document.removeEventListener('mousedown', onDocClick);
      document.removeEventListener('keydown', onEsc);
    };
  }, [open]);

  const items = [
    onView && { label: t('actions.view', { defaultValue: 'View' }), onSelect: onView, destructive: false },
    onEdit && { label: t('actions.edit', { defaultValue: 'Edit' }), onSelect: onEdit, destructive: false },
    onDelete && { label: t('actions.delete', { defaultValue: 'Delete' }), onSelect: onDelete, destructive: true },
    ...(extra ?? []),
  ].filter(Boolean) as { label: string; onSelect: () => void; destructive?: boolean }[];

  // No permitted action → no menu. Better than a ⋯ that opens onto nothing.
  if (items.length === 0) return null;

  return (
    <div className="row-actions" ref={ref}>
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={t('actions.rowMenu', { defaultValue: 'Row actions' })}
        onClick={() => setOpen((v) => !v)}
        data-testid={testId + '-actions'}
      >
        &#8943;
      </button>
      {open && (
        <div role="menu" className="row-actions-menu">
          {items.map((item) => (
            <button
              key={item.label}
              type="button"
              role="menuitem"
              className={item.destructive ? 'is-destructive' : undefined}
              onClick={() => {
                setOpen(false);
                item.onSelect();
              }}
              data-testid={testId + '-action-' + item.label.toLowerCase().replace(/\s+/g, '-')}
            >
              {item.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
